# Configuration management: layered static + dynamic config with hot reload.
# Demonstrates: env vars, file defaults, a polled "remote" config server,
# change listeners, graceful degradation when remote is unreachable.
import os, json, time, threading, random

# Layer 1: base defaults from a file (would be config/app.json on disk).
BASE_FILE_CONFIG = {"db_pool_size": 10, "rate_limit_rps": 1000,
                    "feature_new_checkout": False, "cb_threshold": 0.5}

# A pretend remote config server (in reality: Spring Cloud Config, Consul KV,
# AWS Parameter Store). Returns a dict and occasionally changes a value.
class RemoteConfigServer:
    def __init__(self):
        self.state = {"rate_limit_rps": 1500, "feature_new_checkout": False}
    def fetch(self):
        # 10% chance to "change" a value, simulating an operator edit.
        if random.random() < 0.10:
            self.state["rate_limit_rps"] = random.choice([800, 1500, 2000])
            self.state["feature_new_checkout"] = random.choice([True, False])
        return dict(self.state)

class ConfigManager:
    def __init__(self, base, remote):
        self.base, self.remote = base, remote
        self.cache, self.version = {}, 0
        self.listeners = {}  # key -> list of callbacks
        self.lock = threading.Lock()
        self._refresh()  # initial load
    def _refresh(self):
        # Layered: env var > remote > base file.  Env wins (operator override).
        new = dict(self.base)
        try:
            new.update(self.remote.fetch())  # remote may raise
        except Exception as e:
            print(f"[config] remote unreachable, using cached: {e}")
        # env var override (e.g., RATE_LIMIT_RPS=500 forces value)
        for k in new:
            env = os.environ.get(k.upper())
            if env is not None:
                new[k] = json.loads(env) if env in "true false" else env
        with self.lock:
            changes = {k: new[k] for k in new if new[k] != self.cache.get(k)}
            self.cache, self.version = new, self.version + 1
        # fire hot-reload listeners for changed keys
        for k, v in changes.items():
            for cb in self.listeners.get(k, []):
                cb(v)
    def get(self, key):
        with self.lock:
            return self.cache.get(key)
    def on_change(self, key, cb):
        self.listeners.setdefault(key, []).append(cb)
    def start_polling(self, interval=5):
        def loop():
            while True:
                time.sleep(interval)
                self._refresh()
        threading.Thread(target=loop, daemon=True).start()

# Demo: a feature flag listener and a circuit-breaker threshold listener.
if __name__ == "__main__":
    mgr = ConfigManager(BASE_FILE_CONFIG, RemoteConfigServer())
    mgr.on_change("feature_new_checkout",
                 lambda v: print(f"[listener] new_checkout -> {v}"))
    mgr.on_change("rate_limit_rps",
                 lambda v: print(f"[listener] rate_limit -> {v} r/s"))
    mgr.start_polling(interval=2)
    for _ in range(15):
        print(f"v={mgr.version} rate={mgr.get('rate_limit_rps')} "
              f"flag={mgr.get('feature_new_checkout')}")
        time.sleep(2)
